338	      // Real ASR word timestamps from transcripts/screen.json, shifted so the
339	      // first word ("Hey") lands at t=0. Original "Hey" started at 2.42s.
340	      const introWords = [
341	        { id: "w1", start: 0.0 },
342	        { id: "w2", start: 0.52 },
343	        { id: "w3", start: 1.08 },
344	        { id: "w4", start: 1.44 },
345	        { id: "w5", start: 1.62 },
346	        { id: "w6", start: 1.76 },
