352	        { id: "w12", start: 3.6 },
353	        { id: "w13", start: 4.04 },
354	      ];
355	
356	      const heroWords = [
357	        { id: "h1", start: 5.0 },
358	        { id: "h2", start: 5.32 },
359	        { id: "h3", start: 5.64 },
360	        { id: "h4", start: 6.08 },
361	        { id: "h5", start: 6.22 },
362	        { id: "h6", start: 6.46 },
363	        { id: "h7", start: 6.84 },
364	        { id: "h8", start: 7.18 },
365	      ];
