367	      // ---- Background: continuous forward motion through the whole shot ----
368	
369	      // Perspective grid scrolls toward camera for the entire composition —
370	      // one continuous linear sweep, exactly 8 tile-heights (8 x 96px) so it
371	      // stays seamless without needing an infinite repeat.
372	      tl.fromTo(
373	        "#grid-plane",
374	        { backgroundPosition: "0px 0px" },
375	        { backgroundPosition: "0px 768px", duration: COMP_DURATION, ease: "none" },
376	        0,
377	      );
378	
379	      // Sun bloom breathes gently — idle ambient life behind the horizon.
380	      tl.fromTo(
381	        "#sun-glow",
382	        { opacity: 0.75, scale: 1 },
383	        {
384	          opacity: 1,
385	          scale: 1.06,
386	          duration: COMP_DURATION / 2,
387	          ease: "sine.inOut",
388	          yoyo: true,
389	          repeat: 1,
