422	      // dim slightly so it reads as a subordinate lead-in line.
423	      tl.fromTo(
424	        "#intro-line",
425	        { xPercent: -50, opacity: 1, y: 0 },
426	        { xPercent: -50, opacity: 0.55, y: -14, duration: 0.5, ease: "power2.out" },
